/* Shared Grade 11 identity. Secondary Firebase apps keep teacher login separate.
 * Account bindings contain identifiers only; passwords are never saved here. */
const G11CloudIdentity=(()=>{
  let studentApp,provisionApp;
  const app=(name)=>{try{return firebase.app(name);}catch{return firebase.initializeApp(firebaseConfig,name);}};
  const student=()=>studentApp??=(app('grade11-student'));
  const provision=()=>provisionApp??=(app('grade11-provisioning'));
  const stamp=()=>firebase.database.ServerValue.TIMESTAMP;
  async function account(id){const value=(await db.ref('grade11AiAccounts').child(id).once('value')).val();try{localStorage.setItem('cs-report-grade11-binding:'+id,JSON.stringify(value));}catch{}return value;}
  async function cachedAccount(id){let timer;try{return await Promise.race([account(id),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Cloud unavailable')),8000);})]);}catch{try{return JSON.parse(localStorage.getItem('cs-report-grade11-binding:'+id)||'null');}catch{return null;}}finally{clearTimeout(timer);}}
  async function logout(){await student().auth().signOut();try{sessionStorage.removeItem('csReportGrade11Session');}catch{}}
  async function verifyTeacher(){const user=auth.currentUser;if(!user)throw Error('Masuk sebagai guru terlebih dahulu.');const row=(await db.ref('guru').child(user.uid).once('value')).val()||{};if(!isAdminEmail(user.email)&&!(row.isVerified===true&&(row.emailVerified===true||user.emailVerified===true)))throw Error('Akun guru belum terverifikasi.');return user;}
  async function newAccount(studentRow,password){await verifyTeacher();if(!/^11/.test(String(studentRow.kelas).replace(/^Grade\s*/i,'')))throw Error('Akun cloud ini khusus kelas 11.');if(typeof password!=='string'||password.length<6)throw Error('Password siswa minimal 6 karakter.');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(studentRow.id))),hex=Array.from(new Uint8Array(bytes)).map(v=>v.toString(16).padStart(2,'0')).join('').slice(0,32),nonce=crypto.getRandomValues(new Uint32Array(2)).join('');const email='g11.'+hex+'.'+nonce+'@students.cs-report.invalid';const secondary=provision();await secondary.auth().setPersistence(firebase.auth.Auth.Persistence.NONE);const created=await secondary.auth().createUserWithEmailAndPassword(email,password);await secondary.auth().signOut();return {uid:created.user.uid,email,grade:11,createdAt:stamp(),createdBy:auth.currentUser.uid};}
  async function activate(studentRow){const existing=await account(studentRow.id);if(existing?.uid)return existing;const created=await newAccount(studentRow,studentRow.password||"Sph12345!");await db.ref('grade11AiAccounts').child(studentRow.id).set(created);return created;}
  async function login(id,password){const binding=await account(id);if(!binding?.uid||!binding.email)throw Error('Akun cloud belum diaktifkan. Minta guru menekan Aktifkan akun cloud pada monitor kelas 11.');const secure=student();await secure.auth().setPersistence(firebase.auth.Auth.Persistence.LOCAL);const result=await secure.auth().signInWithEmailAndPassword(binding.email,password);if(result.user.uid!==binding.uid){await secure.auth().signOut();throw Error('Akun cloud tidak cocok. Masuk kembali dari CS.Report.');}return result.user;}
  async function restore(id){const secure=student();const user=await new Promise(resolve=>{let off=()=>{};off=secure.auth().onAuthStateChanged(u=>{resolve(u);queueMicrotask(()=>off());});});const binding=await cachedAccount(id);if(!user||user.uid!==binding?.uid)throw Error('Sesi cloud berakhir. Masuk kembali melalui nama dan password CS.Report.');return {user,db:secure.database(),binding};}
  async function changeOwnPassword(row,oldPassword,newPassword){const user=await login(row.id,oldPassword);await user.updatePassword(newPassword);try{await student().database().ref('siswa').child(row.id).update({password:newPassword,pendingPassword:null,pendingPasswordAt:null});}catch(error){try{await user.updatePassword(oldPassword);}catch{}throw error;}}
  async function updateTeacherStudent(row,patch){const update={...patch},old=await account(row.id);if(old?.uid&&typeof patch.password==='string'&&patch.password!==row.password){const created=await newAccount(row,patch.password),multi={};for(const [key,value]of Object.entries(update))multi['siswa/'+row.id+'/'+key]=value;multi['grade11AiAccounts/'+row.id]=created;await db.ref().update(multi);}else await siswaRef.child(row.id).update(update);}
  return {logout,account,activate,login,restore,changeOwnPassword,updateTeacherStudent,verifyTeacher,stamp};
})();
